+    public void testDateHistogram() throws Exception {
+        for (int i = 0; i < 3; i++) {
+            try (RestClient localClient = newLocalClient()) {
+                Request request = new Request("POST", "/" + queryIndices + "/_search");
+                request.setJsonEntity("""
+                        {
+                          "aggs": {
+                            "hist": {
