+                case DAY_OF_MONTH -> days != null;
+                case HOUR_OF_DAY -> hours != null;
+                case MINUTE_OF_HOUR -> minutes != null;
+                case SECOND_OF_MINUTE -> seconds != null;
+                case INSTANT_SECONDS -> months != null && days != null && hours != null && minutes != null && seconds != null;
